      const last = Number(S.last_ts || 0);
      const age = (last > 0) ? Math.max(0, now - last) : 1e15;

      const healthy = (enabled === 1 && errs === 0 && age < Math.max(10_000, (interval > 0 ? interval*6 : 12_000))) ? 1 : 0;

